// @FIGURE_CODE_BEGIN
// Trajectory model: parabola through origin, apex ~155 ft near x ≈ 290, landing ~565 ft.
var X_MAX = 565;
function h(x) { return 0.001942 * x * (X_MAX - x); }
var WALL_H = 40; // wall height (ft)

var ballX = 200, wallX = 400, sampled = false;

var trajPts = [];
for (var x = 0; x <= X_MAX; x += 5) trajPts.push({ x: x, y: h(x) });

var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

var arrowPlugin = {
  id: 'figAnno',
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx, xa = chart.scales.x, ya = chart.scales.y;
    var px = function (x) { return xa.getPixelForValue(x); };
    var py = function (y) { return ya.getPixelForValue(y); };
    ctx.save();

    // Direction arrowheads along the curve
    [40, 120, 205, 330, 475, 555].forEach(function (ax) {
      var dy = (h(ax + 2) - h(ax - 2)) / 4;
      var ang = Math.atan2(-(dy) * (chart.scales.y.getPixelForValue(0) - chart.scales.y.getPixelForValue(1)),
        chart.scales.x.getPixelForValue(1) - chart.scales.x.getPixelForValue(0));
      var cx0 = px(ax), cy0 = py(h(ax));
      ctx.fillStyle = '#0e7c8c';
      ctx.beginPath();
      ctx.moveTo(cx0 + 9 * Math.cos(ang), cy0 + 9 * Math.sin(ang));
      ctx.lineTo(cx0 + 9 * Math.cos(ang + 2.5), cy0 + 9 * Math.sin(ang + 2.5));
      ctx.lineTo(cx0 + 9 * Math.cos(ang - 2.5), cy0 + 9 * Math.sin(ang - 2.5));
      ctx.closePath(); ctx.fill();
    });

    // Leader: Position of hitter → origin
    ctx.strokeStyle = '#555'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(px(15), py(38)); ctx.lineTo(px(70), py(28)); ctx.stroke();
    label(ctx, 'Position of hitter', px(75), py(26), '#333', 'left');

    // Leader: Trajectory of ball → point on rising branch (200)
    ctx.beginPath(); ctx.moveTo(px(196), py(h(196)) + 6); ctx.lineTo(px(150), py(215)); ctx.stroke();
    label(ctx, 'Trajectory of ball', px(148), py(225), '#333', 'center');

    // Wall: red rectangle on x-axis
    var wx = px(wallX);
    ctx.fillStyle = '#d33';
    ctx.fillRect(wx - 4, py(WALL_H), 8, py(0) - py(WALL_H));
    label(ctx, 'Outfield wall', px(wallX - 30), py(20), '#333', 'right');

    // Clearance indicator at wall
    var bh = h(wallX);
    var clear = bh >= WALL_H;
    ctx.fillStyle = clear ? '#1a8a3a' : '#c02222';
    ctx.font = 'bold 11px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText(clear ? '✓ clears (ball ' + Math.round(bh) + ' ft > wall ' + WALL_H + ' ft)'
      : '✗ short (ball ' + Math.round(bh) + ' ft < wall ' + WALL_H + ' ft)', wx + 8, py(WALL_H) + 4);

    // Ball marker drop line + readout
    var bx = px(ballX), by = py(h(ballX));
    ctx.strokeStyle = '#0e7c8c'; ctx.setLineDash([3, 3]);
    ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx, py(0)); ctx.stroke();
    ctx.setLineDash([]);
    ctx.beginPath(); ctx.arc(bx, by, 6, 0, Math.PI * 2);
    ctx.fillStyle = '#fff'; ctx.fill();
    ctx.strokeStyle = '#e8912d'; ctx.lineWidth = 2.5; ctx.stroke();
    ctx.fillStyle = '#0e7c8c';
    ctx.beginPath(); ctx.arc(bx, by, 2.5, 0, Math.PI * 2); ctx.fill();
    label(ctx, '(' + ballX + ' ft, ' + Math.round(h(ballX)) + ' ft)', bx + 10, by - 10, '#0e7c8c', 'left');

    ctx.restore();

    function label(c, text, x, y, color, align) {
      c.font = '12px sans-serif'; c.textAlign = align || 'left';
      c.lineWidth = 3; c.strokeStyle = '#fff'; c.strokeText(text, x, y);
      c.fillStyle = color; c.fillText(text, x, y);
    }
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [{
      label: 'Trajectory of ball',
      data: trajPts,
      borderColor: '#0e7c8c',
      borderWidth: 2.5,
      pointRadius: 0,
      pointBackgroundColor: '#0e7c8c',
      showLine: true,
      fill: false
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          title: function (items) { return 'Distance: ' + items[0].parsed.x + ' ft'; },
          label: function (item) { return 'Height: ' + Math.round(item.parsed.y) + ' ft'; }
        }
      }
    },
    scales: {
      x: {
        type: 'linear', min: 0, max: 600,
        title: { display: true, text: 'Distance (ft)', font: { size: 13 } },
        ticks: { stepSize: 100 },
        grid: { color: 'rgba(0,0,0,0.12)', borderDash: [2, 3] }
      },
      y: {
        min: 0, max: 320,
        title: { display: true, text: 'Height (ft)', font: { size: 13 } },
        ticks: { stepSize: 100 },
        grid: { color: 'rgba(0,0,0,0.12)', borderDash: [2, 3] }
      }
    }
  },
  plugins: [arrowPlugin]
});
window.__markRendered();

function refresh() {
  chart.data.datasets[0].showLine = !sampled;
  chart.data.datasets[0].pointRadius = sampled ? 3 : 0;
  chart.update();
}

function update_ballDistance(v) { ballX = v; chart.update(); }
function update_wallPosition(v) { wallX = v; chart.update(); }
function toggle_viewMode(on) { sampled = on; refresh(); }

var steps = [
  { narration: "Drag the ball marker along the arc: at each distance from the hitter, the readout gives the ball's height. The curve climbs to a peak just over 150 ft near 290 ft, then falls.", state: { ballDistance: 200, wallPosition: 400, sampled: false } },
  { narration: "With the wall at 400 ft, the ball is still well above it — the figure highlights the clearance. Slide the wall right toward 550 ft and watch the margin shrink until the ball arrives below the top of the wall.", state: { ballDistance: 400, wallPosition: 400, sampled: false } },
  { narration: "Switch to sampled points: the smooth arc becomes discrete distance–height pairs on the grid — the same function you would see in a table of values.", state: { ballDistance: 400, wallPosition: 400, sampled: true } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' of ' + steps.length;
  var bi = document.getElementById('ballDistanceInput');
  bi.value = s.state.ballDistance;
  document.getElementById('ballDistanceVal').value = s.state.ballDistance;
  update_ballDistance(s.state.ballDistance);
  var wi = document.getElementById('wallPositionInput');
  wi.value = s.state.wallPosition;
  document.getElementById('wallPositionVal').value = s.state.wallPosition;
  update_wallPosition(s.state.wallPosition);
  document.getElementById('viewModeInput').checked = s.state.sampled;
  toggle_viewMode(s.state.sampled);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
applyStep(0);
// @FIGURE_CODE_END

